var LAYOUTS={
  center:{name:'水平垂直居中', css:'.layout{display:flex;align-items:center;justify-content:center;min-height:180px;}', kids:['box']},
  sidebar:{name:'侧边栏 + 主内容', css:'.layout{display:flex;gap:16px;}\n.layout > .col-aside{width:180px;flex:0 0 180px;}\n.layout > .col-main{flex:1;}', kids:['aside','main']},
  holygrail:{name:'圣杯（三栏）', css:'.layout{display:flex;gap:16px;}\n.layout > .col-nav{width:140px;flex:0 0 140px;order:-1;}\n.layout > .col-main{flex:1;}\n.layout > .col-aside{width:160px;flex:0 0 160px;}', kids:['main','nav','aside']},
  grid:{name:'等宽自适应网格', css:'.layout{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:16px;}', kids:['box','box','box','box']},
  stack:{name:'纵向堆叠', css:'.layout{display:flex;flex-direction:column;gap:12px;}', kids:['bar','bar','bar']}
};
function layoutCss(key, opts){
  opts=opts||{}; var k=key||'center';
  var L=LAYOUTS[k];
  if(!L) return {ok:false, reason:'unknown layout'};
  var gap=opts.gap!=null?opts.gap:16;
  var css=L.css.replace(/gap:\s*\d+px/g,'gap: '+gap+'px');
  return {ok:true, name:L.name, css:css, kids:L.kids.slice()};
}

var EXPORTS={layoutCss:layoutCss,LAYOUTS:LAYOUTS};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.LayoutForgePure = EXPORTS; }
